#!/bin/bash
read -p "Enter a color: " color

case "$color" in
    red|Red|RED)
        echo "Primary color"
        ;;
    blue|Blue|BLUE)
        echo "Primary color"
        ;;
    green|Green|GREEN)
        echo "Secondary color"
        ;;
    *)
        echo "Unknown color"
        ;;
esac

Defining Functions:
#!/bin/bash
greet() {
    local name="$1"
    echo "Hello, $name!"
}

# Call the function
greet "Alice"
greet "Bob"

# Function with return
is_even() {
    local num=$1
    return $((num % 2))
}

if is_even 4; then
    echo "Even"
fi

Argument Parsing with getopts:
#!/bin/bash
usage() {
    echo "Usage: $0 [-n name] [-a age] [-v]"
    exit 1
}

verbose=false
while getopts "n:a:v" opt; do
    case $opt in
        n) name="$OPTARG" ;;
        a) age="$OPTARG" ;;
        v) verbose=true ;;
        *) usage ;;
    esac
done

echo "Name: ${name:-unknown}"
echo "Age: ${age:-unknown}"
$verbose && echo "Verbose mode on"
